using System.Diagnostics;
using System.Linq.Expressions;
using System.Reflection;
using System.Runtime.CompilerServices;
using System.Text.Json;
using CombatSolver;
using CombatSolver.Engine.InCombat.Simulation;
using HarmonyLib;

namespace OfflineSearchHarness;

// Observation only. Every original Snapshot completes, and no cached result is returned.
internal static class BoundedSnapshotValuesProbe
{
    private const int MaximumEnemies = 32;
    private const int MaximumDeaths = 32;
    private static readonly object Gate = new();
    private static readonly List<string> Names = [];
    private static readonly List<string> Excluded = [];
    private static readonly Action<SimulationSnapshot, long[]> ReadAtoms = BuildReader();
    private static readonly int FixedWidth = Names.Count;
    private static readonly int Width = FixedWidth + 2 + MaximumEnemies * 2 + MaximumDeaths;
    private static readonly Lru[] Caches = [new(128, true), new(1024, true), new(8192, true), new(65536, true), new(65536, false)];
    private static readonly ConditionalWeakTable<CombatRootSnapshot, Identity> Roots = new();
    private static readonly ConditionalWeakTable<CombatBeamSolver, SolverInfo> Solvers = new();
    private static readonly Dictionary<string, int> Contexts = new(StringComparer.Ordinal);
    private static readonly List<object> ContextRows = [];
    private static readonly FieldInfo[] SolverFields = typeof(CombatBeamSolver).GetFields(BindingFlags.Instance | BindingFlags.NonPublic);
    private static int _nextRoot, _nextSolver, _nextMember;
    private static long _total, _refusedExtras, _refusedEnemies, _refusedDeaths, _observerTicks;
    [ThreadStatic] private static long[]? _buffer;
    private sealed record Identity(int Id);
    private sealed record SolverInfo(int Solver, int Member, int Root, int Context);
    private readonly record struct Key(int Root, int Context, StateFingerprint State, int Actions,
        SearchBoundaryReason Boundary, int HpLost, int Recovered, int History);

    internal static void Install(string output)
    {
        if (Environment.GetEnvironmentVariable("OFFLINE_HARNESS_BOUNDED_VALUES") != "1") return;
        Names.Add("EnemyDurabilityByCombatId.Count");
        Names.Add("ProcessedEnemyDeaths.Count");
        for (int i = 0; i < MaximumEnemies; i++)
        {
            Names.Add($"EnemyDurabilityByCombatId[{i}].CombatId");
            Names.Add($"EnemyDurabilityByCombatId[{i}].Durability");
        }
        for (int i = 0; i < MaximumDeaths; i++) Names.Add($"ProcessedEnemyDeaths[{i}]");
        GameBootstrap.Harmony.Patch(AccessTools.Method(typeof(CombatBeamSolver), "CreateExpansionWorker"),
            postfix: new HarmonyMethod(typeof(BoundedSnapshotValuesProbe), nameof(Worker)));
        GameBootstrap.Harmony.Patch(AccessTools.Method(typeof(CombatBeamSolver), "Snapshot"),
            postfix: new HarmonyMethod(typeof(BoundedSnapshotValuesProbe), nameof(Observe)));
        AppDomain.CurrentDomain.ProcessExit += (_, _) =>
        {
            lock (Gate) File.WriteAllText(Path.Combine(output, "bounded-snapshot-values.json"),
                JsonSerializer.Serialize(new
                {
                    observationOnly = true,
                    scope = "Completed owned Snapshot value properties, flattened scalar structs, exact enemy durability and sorted processed deaths. No simulator/model graphs retained. Equality is an opportunity check, not getter purity or cache safety proof.",
                    keyScope = "Exact captured root identity plus observed frozen evaluation settings, StateKey, action count and boundary. Augmented key additionally includes cumulative HP lost, recovered HP and history count. Unknown callback audiences and full dependency closure remain unproved.",
                    excluded = Excluded, atomNames = Names, width = Width,
                    _total, _refusedExtras, _refusedEnemies, _refusedDeaths,
                    observerAccumulatedElapsedSeconds = (double)_observerTicks / Stopwatch.Frequency,
                    observerTimeScope = "Accumulated elapsed including lock wait, scheduling and GC, not CPU or performance acceptance.",
                    roots = _nextRoot, solvers = _nextSolver, members = _nextMember,
                    contexts = ContextRows,
                    caches = Caches.Select(c => c.Result()),
                }, new JsonSerializerOptions { WriteIndented = true }));
        };
    }

    private static Action<SimulationSnapshot, long[]> BuildReader()
    {
        ParameterExpression snapshot = Expression.Parameter(typeof(SimulationSnapshot), "s");
        ParameterExpression target = Expression.Parameter(typeof(long[]), "bits");
        List<Expression> writes = [];
        void Add(string name, Expression value)
        {
            Expression bits;
            if (value.Type == typeof(double))
                bits = Expression.Call(typeof(BitConverter).GetMethod(nameof(BitConverter.DoubleToInt64Bits))!, value);
            else if (value.Type == typeof(bool))
                bits = Expression.Condition(value, Expression.Constant(1L), Expression.Constant(0L));
            else bits = Expression.Convert(value, typeof(long));
            writes.Add(Expression.Assign(Expression.ArrayAccess(target, Expression.Constant(Names.Count)), bits));
            Names.Add(name);
        }
        void Flatten(string name, Expression value)
        {
            Type type = value.Type;
            Type? nullable = Nullable.GetUnderlyingType(type);
            if (nullable != null)
            {
                Add(name + ".HasValue", Expression.Property(value, "HasValue"));
                Flatten(name + ".ValueOrDefault", Expression.Call(value, type.GetMethod("GetValueOrDefault", Type.EmptyTypes)!));
            }
            else if (type.IsEnum || type == typeof(int) || type == typeof(uint) || type == typeof(long)
                || type == typeof(ulong) || type == typeof(double) || type == typeof(bool)) Add(name, value);
            else if (type == typeof(StateFingerprint) || type == typeof(StrategicEffectVector)
                || type == typeof(RelicCounterEvaluation) || type == typeof(CombatTerminalStamp) || type == typeof(GrowthValues))
            {
                foreach (PropertyInfo property in type.GetProperties(BindingFlags.Instance | BindingFlags.Public).OrderBy(p => p.Name, StringComparer.Ordinal))
                {
                    if (type == typeof(GrowthValues) && property.Name is "Extras" or "ThirdParty")
                    {
                        Excluded.Add(name + "." + property.Name + " (nonempty Extras refuses sample)");
                        continue;
                    }
                    if (property.GetIndexParameters().Length != 0) throw new InvalidOperationException("Unexpected value indexer.");
                    Flatten(name + "." + property.Name, Expression.Property(value, property));
                }
            }
            else throw new InvalidOperationException($"Unaudited Snapshot value type {name}: {type}.");
        }
        foreach (PropertyInfo property in typeof(SimulationSnapshot).GetProperties(BindingFlags.Instance | BindingFlags.Public).OrderBy(p => p.Name, StringComparer.Ordinal))
        {
            if (property.Name is "Simulator" or "HasSimulator" or "PredictionGaps")
            {
                Excluded.Add(property.Name + " (reference/lifecycle output not compared)");
                continue;
            }
            if (property.Name is "EnemyDurabilityByCombatId" or "ProcessedEnemyDeaths") continue;
            Flatten(property.Name, Expression.Property(snapshot, property));
        }
        writes.Add(Expression.Empty());
        return Expression.Lambda<Action<SimulationSnapshot, long[]>>(Expression.Block(writes), snapshot, target).Compile();
    }

    private static object? Field(CombatBeamSolver solver, string name) =>
        SolverFields.Single(f => f.Name == name).GetValue(solver);

    private static SolverInfo Info(CombatBeamSolver solver) => Solvers.GetValue(solver, s => CreateInfo(s, ++_nextMember));

    private static SolverInfo CreateInfo(CombatBeamSolver s, int member)
    {
        var root = (CombatRootSnapshot)SolverFields.Single(f => f.FieldType == typeof(CombatRootSnapshot)).GetValue(s)!;
        var policy = (SearchPolicySnapshot)SolverFields.Single(f => f.FieldType == typeof(SearchPolicySnapshot)).GetValue(s)!;
        string[] fieldNames = ["_startTurnNumber", "_ignoreLongTermRewards", "_strategicBossHpRelief", "_growthBudgets", "_relicTargets", "_theftPolicy", "_maximumPotionUses", "_minimumPotionUses", "_earliestPotionTurn"];
        var values = fieldNames.ToDictionary(name => name, name => Field(s, name));
        values.Add("Act3BossStrategy", policy.Act3BossStrategy);
        values.Add("StateKeySalt", policy.StateKeySalt);
        values.Add("PileOrderInvariantMask", policy.PileOrderInvariantMask);
        string context = JsonSerializer.Serialize(values);
        if (!Contexts.TryGetValue(context, out int contextId))
        {
            contextId = Contexts.Count + 1;
            Contexts.Add(context, contextId);
            ContextRows.Add(new { id = contextId, values });
        }
        return new(++_nextSolver, member, Roots.GetValue(root, _ => new(++_nextRoot)).Id, contextId);
    }

    private static void Worker(CombatBeamSolver __instance, CombatBeamSolver __result)
    {
        lock (Gate)
        {
            SolverInfo parent = Info(__instance);
            Solvers.Add(__result, CreateInfo(__result, parent.Member));
        }
    }

    private static void Observe(CombatBeamSolver __instance, int actionCount, SimulationSnapshot __result)
    {
        long start = Stopwatch.GetTimestamp();
        lock (Gate)
        {
            _total++;
            if (!__result.GrowthRewards.Extras.IsEmpty) { _refusedExtras++; return; }
            if (__result.EnemyDurabilityByCombatId.Count > MaximumEnemies) { _refusedEnemies++; return; }
            if (__result.ProcessedEnemyDeaths.Count > MaximumDeaths) { _refusedDeaths++; return; }
            SolverInfo info = Info(__instance);
            long[] buffer = _buffer ??= new long[Width];
            ReadAtoms(__result, buffer);
            Array.Clear(buffer, FixedWidth, Width - FixedWidth);
            buffer[FixedWidth] = __result.EnemyDurabilityByCombatId.Count;
            buffer[FixedWidth + 1] = __result.ProcessedEnemyDeaths.Count;
            for (int i = 0; i < __result.EnemyDurabilityByCombatId.Count; i++)
            {
                EnemyDurabilityEntry value = __result.EnemyDurabilityByCombatId[i];
                buffer[FixedWidth + 2 + 2 * i] = value.CombatId;
                buffer[FixedWidth + 3 + 2 * i] = value.Durability;
            }
            Span<long> deaths = buffer.AsSpan(FixedWidth + 2 + MaximumEnemies * 2, __result.ProcessedEnemyDeaths.Count);
            int d = 0;
            foreach (uint id in __result.ProcessedEnemyDeaths) deaths[d++] = id;
            deaths.Sort();
            var key = new Key(info.Root, info.Context, __result.StateKey, actionCount, __result.BoundaryReason,
                __result.CumulativePlayerHpLost, __result.RecoveredPlayerHp, __result.HistoryEntryCount);
            foreach (Lru cache in Caches) cache.Observe(key, info, buffer);
            _observerTicks += Stopwatch.GetTimestamp() - start;
        }
    }

    private sealed class Lru(int capacity, bool augmented)
    {
        private readonly Dictionary<Key, int> _indices = new(capacity);
        private readonly Entry[] _entries = new Entry[capacity];
        private readonly long[] _values = new long[checked(capacity * Width)];
        private readonly long[] _differences = new long[Width];
        private readonly List<object> _examples = [];
        private int _count, _head = -1, _tail = -1;
        private long _queries, _hits, _equal, _sameWorker, _crossWorker, _crossMember, _equalCrossMember, _mismatches, _evictions;
        private struct Entry { public Key Key; public int Solver, Member, Previous, Next; }

        public void Observe(Key key, SolverInfo info, long[] bits)
        {
            _queries++;
            if (!augmented) key = key with { HpLost = 0, Recovered = 0, History = 0 };
            int slot;
            if (_indices.TryGetValue(key, out slot))
            {
                _hits++;
                Entry prior = _entries[slot];
                if (prior.Member != info.Member) _crossMember++;
                else if (prior.Solver == info.Solver) _sameWorker++;
                else _crossWorker++;
                ReadOnlySpan<long> saved = _values.AsSpan(slot * Width, Width);
                bool same = saved.SequenceEqual(bits);
                if (same)
                {
                    _equal++;
                    if (prior.Member != info.Member) _equalCrossMember++;
                }
                else
                {
                    _mismatches++;
                    List<object>? example = _examples.Count < 12 ? [] : null;
                    for (int i = 0; i < Width; i++)
                        if (saved[i] != bits[i])
                        {
                            _differences[i]++;
                            example?.Add(new { field = Names[i], beforeBits = saved[i], afterBits = bits[i] });
                        }
                    if (example != null) _examples.Add(new { key, prior.Member, currentMember = info.Member, differences = example });
                }
                Unlink(slot);
            }
            else
            {
                if (_count == capacity)
                {
                    slot = _tail;
                    _indices.Remove(_entries[slot].Key);
                    Unlink(slot);
                    _evictions++;
                }
                else slot = _count++;
                _indices.Add(key, slot);
            }
            bits.CopyTo(_values, slot * Width);
            _entries[slot] = new() { Key = key, Solver = info.Solver, Member = info.Member, Previous = -1, Next = _head };
            if (_head >= 0) _entries[_head].Previous = slot;
            _head = slot;
            if (_tail < 0) _tail = slot;
        }

        private void Unlink(int slot)
        {
            Entry item = _entries[slot];
            if (item.Previous >= 0) _entries[item.Previous].Next = item.Next; else _head = item.Next;
            if (item.Next >= 0) _entries[item.Next].Previous = item.Previous; else _tail = item.Previous;
        }

        public object Result() => new
        {
            capacity, augmented, _queries, _hits, _equal, _sameWorker, _crossWorker, _crossMember, _equalCrossMember, _mismatches, _evictions,
            retained = _count, exactValuePayloadBytes = (long)_values.Length * sizeof(long),
            equalRate = _queries == 0 ? 0 : (double)_equal / _queries,
            differences = Names.Select((name, index) => new { name, count = _differences[index] }).Where(x => x.count != 0),
            examples = _examples,
            recency = "LRU access order at serialized observer. Most recent observed value replaces mismatch; original computation always runs. Worker completion order may vary.",
        };
    }
}

using System.Diagnostics;
using System.Reflection;
using System.Text.Json;
using System.Text.Json.Serialization;
using CombatSolver;
using MegaCrit.Sts2.Core.Combat;

namespace OfflineSearchHarness;

internal static class Program
{
    private static readonly JsonSerializerOptions Json = new()
    {
        WriteIndented = true,
        DefaultIgnoreCondition = JsonIgnoreCondition.WhenWritingNull,
        Encoder = System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping,
    };

    private static int Main(string[] rawArgs)
    {
        if (rawArgs.Length == 1 && rawArgs[0] == "--check-primary-incumbents")
            return PrimaryIncumbentChecks.Run();
        if (rawArgs.Length == 1 && rawArgs[0] == "--check-early-turn-continuation-bound")
        {
            return EarlyTurnContinuationChecks.Run();
        }
        if (rawArgs.Length == 3 && rawArgs[0] == "--compare-quality-batch")
            return QualityComparison.Run(rawArgs[1], rawArgs[2]);
        if (rawArgs.Length == 2 && rawArgs[0] == "--ranking-schema")
            return RankingChecks.WriteSchema(rawArgs[1]);
        if (rawArgs.Length == 3 && rawArgs[0] == "--check-ranking")
            return RankingChecks.Run(rawArgs[1], rawArgs[2]);
        HarnessOptions options;
        try
        {
            options = HarnessOptions.Parse(rawArgs);
        }
        catch (Exception error)
        {
            Console.Error.WriteLine(error.Message);
            Console.Error.WriteLine(HarnessOptions.Usage);
            return 2;
        }

        HarnessLog.VerboseGameLog = options.VerboseGameLog;
        HarnessLog.Language = options.Language;
        Directory.CreateDirectory(options.OutputDirectory);

        List<StepRecord> steps = [];
        Dictionary<string, object?> payload = new()
        {
            ["label"] = options.Label,
            ["scenario"] = options.Scenario,
            ["requestPath"] = options.RequestPath,
            ["milestone"] = options.Milestone,
        };

        string reached = "none";
        int exitCode = 0;
        IDisposable? choiceScope = null;
        try
        {
            MainLoopContext loop = new();
            SynchronizationContext.SetSynchronizationContext(loop);

            Step(steps, "M0.1 装 Godot 绕过补丁", () =>
            {
                GameBootstrap.ApplyGodotBypasses();
                int nodeCctors = GameBootstrap.SkipGodotNodeStaticConstructors();
                return $"{GameBootstrap.Bypasses.Count} 处绕过（含 {nodeCctors} 个节点静态构造）";
            });
            Step(steps, "M0.2 初始化游戏静态状态", GameBootstrap.InitializeStaticState);
            Step(steps, "M0.3 初始化模组运行期状态", () => ModRuntime.Initialize(options));
            DuplicateChoiceProbe.Install(options.OutputDirectory);
            EquivalenceProbe.Install(options.OutputDirectory);
            SnapshotOpportunityProbe.Install(options.OutputDirectory);
            ShuffleProjectionOpportunityProbe.Install(options.OutputDirectory);
            if (Environment.GetEnvironmentVariable("OFFLINE_HARNESS_PROBE_STATICS") is { Length: > 0 } filter)
                Step(steps, "P 静态构造探针", () => $"types={GameBootstrap.ProbeStaticConstructors(filter)}");
            GeneratedScenarioSetup? generated = null;
            if (Environment.GetEnvironmentVariable("OFFLINE_HARNESS_MEMORY_DISPLAY_CHECKS") == "1")
                MemoryDisplayChecks.Run();
            if (Environment.GetEnvironmentVariable("OFFLINE_HARNESS_MEMORY_DISPLAY_CHECKS") == "baseline")
                MemoryDisplayChecks.ReproduceOldCapacity();
            UnattendedTestRunner.OfflineScenarioSession? session = null;
            CombatState? combat = null;

            if (options.RequestPath != null)
            {
                Step(steps, "G1.1 解析生成场景请求", () =>
                {
                    UnattendedTestRequest request = GeneratedScenarioSetup.ReadRequest(options.RequestPath);
                    generated = GeneratedScenarioSetup.Prepare(
                        request, Path.Combine(options.OutputDirectory, "evidence"));
                    session = generated.Session;
                    return $"character={generated.Request.CharacterId} encounter={generated.Request.EncounterId} "
                        + $"generated={generated.Resolved != null}";
                });
                payload["scenario"] = new HarnessScenario(
                    generated!.Request.CharacterId, generated.Request.EncounterId,
                    generated.Request.Seed, generated.Request.Ascension,
                    generated.Request.ActIndexForTest);
                payload["resolvedScenario"] = generated!.Resolved?.Options;
                payload["catalogFingerprint"] = generated.Resolved?.CatalogFingerprint;

                Step(steps, "G1.2 建跑局、注入装备、进遭遇战房间", () =>
                {
                    Task<IDisposable?> enter = generated!.EnterCombatRoomAsync();
                    loop.RunUntilCompleted(enter, TimeSpan.FromSeconds(300), "生成场景进房");
                    choiceScope = enter.GetAwaiter().GetResult();
                    return $"pumped={loop.PumpedCallbacks}";
                });
                Step(steps, "G1.3 推进到玩家第一回合", () =>
                {
                    combat = OfflineCombat.WaitForPlayableCombat(loop);
                    generated!.CaptureOpening(combat);
                    if (!generated.Request.PreserveNativeCombatStateForTest)
                        loop.RunUntilCompleted(generated.Session.InjectInitialStateAsync(
                            combat, MegaCrit.Sts2.Core.Context.LocalContext.GetMe(combat)!),
                            TimeSpan.FromSeconds(30), "固定夹具状态注入");
                    return OfflineCombat.DescribeRoot(combat);
                });
                payload["setupChoices"] = generated.SetupChoices;
            }
            else
            {
                session = UnattendedTestRunner.OfflineScenarioSession.Create(new UnattendedTestRequest());
                Step(steps, "M1.1 建跑局并进入遭遇战房间", () =>
                {
                    Task enter = OfflineCombat.EnterCombatRoomAsync(options.Scenario);
                    loop.RunUntilCompleted(enter, TimeSpan.FromSeconds(180), "EnterRoomDebug");
                    return $"pumped={loop.PumpedCallbacks}";
                });
                Step(steps, "M1.2 推进到玩家第一回合", () =>
                {
                    combat = OfflineCombat.WaitForPlayableCombat(loop);
                    return OfflineCombat.DescribeRoot(combat);
                });
            }

            reached = "M1";
            if (generated?.Request.TheftPolicyForTest is { } theftPolicy)
                SolverController.SetTheftPolicyForTesting(combat!, theftPolicy);
            if (Environment.GetEnvironmentVariable("OFFLINE_HARNESS_THEFT_BUCKET_CHECKS") == "1")
                PrimaryIncumbentChecks.RunTheft(combat!);
            if (Environment.GetEnvironmentVariable("OFFLINE_HARNESS_RESOURCE_BUCKET_CHECKS") == "1")
                PrimaryIncumbentChecks.RunResources(combat!);
            DuplicateChoiceProbe.RunBuilders(combat!, options.OutputDirectory);
            SnapshotOpportunityProbe.RunShuffleWitness(combat!, options.OutputDirectory);
            if (Environment.GetEnvironmentVariable("OFFLINE_HARNESS_HISTORY_CHECKS") == "1")
                HistoryCounterChecks.Run(combat!, options.OutputDirectory);
            if (Environment.GetEnvironmentVariable("OFFLINE_HARNESS_INFUSED_CORE_CHECKS") == "1")
                InfusedCoreChecks.Run(combat!, options.OutputDirectory);
            payload["budget"] = DescribeBudget(options);
            payload["root"] = OfflineCombat.DescribeRoot(combat!);
            string diagnostics = ModRuntime.DescribeStart(combat!);
            payload["rootDiagnostics"] = diagnostics;
            File.WriteAllText(Path.Combine(options.OutputDirectory, "root-diagnostics.txt"), diagnostics);
            WriteProgress(options, "M1", "ok", "已到达玩家第一回合");

            if (Environment.GetEnvironmentVariable("OFFLINE_HARNESS_FIXED_PREFIX_CONTINUATIONS") == "1")
            {
                Step(steps, "M2 固定长前缀续用测量", () =>
                {
                    payload["fixedPrefixContinuations"] = FixedPrefixContinuationBenchmark.Run(combat!, options, loop);
                    return "N4/N8/N17; fixed-prefix-continuations.json";
                });
                reached = "M2";
            }
            else if (options.Milestone != "M1")
            {
                ModRuntime.SearchOutcome? outcome = null;
                using MemorySampler memory = new(TimeSpan.FromMilliseconds(100));
                Step(steps, $"M2.1 跑一次固定预算搜索（{options.SearchMode}）", () =>
                {
                    outcome = ModRuntime.RunSearchDetailed(combat!, options, loop, session);
                    var solver = outcome.LegacyMetrics;
                    return $"boundary={solver["boundary"]} total_expanded={solver["totalExpanded"]} "
                        + $"total_transitions={solver["totalTransitions"]} score={solver["score"]} "
                        + $"projected_battle_hp_lost={solver["projectedBattleHpLost"]} "
                        + $"wall_s={outcome.WallSeconds:0.00}";
                });
                payload["search"] = new Dictionary<string, object?>
                {
                    ["rootContinuationStamp"] = outcome!.RootContinuationStamp,
                    ["rootLiveStamp"] = outcome.RootLiveStamp,
                    ["rootCapture"] = outcome.RootCapture,
                    ["solverMetrics"] = outcome.LegacyMetrics,
                    ["planActions"] = outcome.PlanActions,
                    ["cachedContinuations"] = outcome.Result.Continuations
                        .Select(item => new
                        {
                            item.StartTurnNumber,
                            item.ForecastOffset,
                            state = item.ExpectedState.StateText,
                        })
                        .ToArray(),
                    ["continuations"] = outcome.Continuations,
                    ["patchLog"] = ModRuntime.PatchLog.ToArray(),
                };
                // 与游戏内 result.json 同名同形的那一份（游戏自己的 Writer 造的）。
                payload["solverMetrics"] = outcome.SolverMetrics;
                // 宿主自己从 SolverResult 读的剪枝/复用计数（游戏内 result.json 没有这些字段）。
                payload["pruneCounters"] = outcome.LegacyMetrics;
                payload["searchPolicy"] = outcome.Policy;
                payload["comparisonQuality"] = outcome.Result.ComparisonQuality;
                payload["phasePerformance"] = ModRuntime.LastPhasePerformance;
                File.WriteAllText(
                    Path.Combine(options.OutputDirectory, "search-policy.json"),
                    JsonSerializer.Serialize(outcome.Policy, UnattendedTestFiles.JsonOptions));
                payload["timeBoundaryObserved"] = outcome.TimeBoundaryObserved;
                payload["wallSeconds"] = outcome.WallSeconds;
                memory.Dispose();
                payload["peakManagedHeapBytes"] = memory.PeakManagedHeapBytes;
                payload["peakManagedLiveBytes"] = memory.PeakManagedLiveBytes;
                payload["peakWorkingSetBytes"] = memory.PeakWorkingSetBytes;
                payload["peakProcessWorkingSetBytes"] = memory.PeakProcessWorkingSetBytes;
                payload["memorySamples"] = memory.Samples;
                payload["totalAllocatedBytes"] = GC.GetTotalAllocatedBytes(precise: false);

                File.WriteAllText(
                    Path.Combine(options.OutputDirectory, "route.json"),
                    JsonSerializer.Serialize(outcome.RouteActions, UnattendedTestFiles.JsonOptions));

                reached = "M2";
                if (Environment.GetEnvironmentVariable("OFFLINE_HARNESS_ANCILLARY_CHECKS") == "1")
                    AncillaryFailureChecks.Run(outcome.Result, options.OutputDirectory);
                WriteProgress(options, "M2", "ok", "搜索完成并产出指标");
            }
        }
        catch (Exception error)
        {
            Exception root = Unwrap(error);
            payload["error"] = new
            {
                type = root.GetType().FullName,
                message = root.Message,
                stack = root.StackTrace,
            };
            WriteProgress(options, NextMilestone(reached), "blocked", $"{root.GetType().Name}: {root.Message}");
            Console.Error.WriteLine($"[FAIL] {root.GetType().Name}: {root.Message}");
            // 包装异常（如 SearchTransitionException）的真正原因在 InnerException 上，必须打出来。
            for (Exception? inner = root.InnerException; inner != null; inner = inner.InnerException)
                Console.Error.WriteLine($"[FAIL:inner] {inner.GetType().Name}: {inner.Message}");
            Console.Error.WriteLine(root.StackTrace);
            exitCode = 1;
        }
        finally
        {
            choiceScope?.Dispose();
            ModRuntime.Session?.Dispose();
            ModRuntime.FlushDiagnostics();
        }

        payload["reachedMilestone"] = reached;
        payload["bypasses"] = GameBootstrap.Bypasses;
        payload["steps"] = steps;
        string resultPath = Path.Combine(options.OutputDirectory, "harness-result.json");
        File.WriteAllText(resultPath, JsonSerializer.Serialize(payload, Json));
        // run_plan.py 直接消费的一份：solverMetrics 与游戏内 result.json 同名同形。
        File.WriteAllText(
            Path.Combine(options.OutputDirectory, "result.json"),
            JsonSerializer.Serialize(new Dictionary<string, object?>
            {
                ["label"] = options.Label,
                ["status"] = exitCode == 0 ? "Passed" : "Failed",
                ["reachedMilestone"] = reached,
                ["requestPath"] = options.RequestPath,
                ["profile"] = options.Profile,
                ["searchMode"] = options.SearchMode,
                ["budget"] = payload.GetValueOrDefault("budget"),
                ["solverMetrics"] = payload.GetValueOrDefault("solverMetrics"),
                ["pruneCounters"] = payload.GetValueOrDefault("pruneCounters"),
                ["timeBoundaryObserved"] = payload.GetValueOrDefault("timeBoundaryObserved"),
                ["wallSeconds"] = payload.GetValueOrDefault("wallSeconds"),
                ["peakManagedHeapBytes"] = payload.GetValueOrDefault("peakManagedHeapBytes"),
                ["peakManagedLiveBytes"] = payload.GetValueOrDefault("peakManagedLiveBytes"),
                ["peakWorkingSetBytes"] = payload.GetValueOrDefault("peakWorkingSetBytes"),
                ["peakProcessWorkingSetBytes"] = payload.GetValueOrDefault("peakProcessWorkingSetBytes"),
                ["totalAllocatedBytes"] = payload.GetValueOrDefault("totalAllocatedBytes"),
                ["rootContinuationStamp"] = payload.GetValueOrDefault("search") is Dictionary<string, object?> s
                    ? s.GetValueOrDefault("rootContinuationStamp")
                    : null,
                ["comparisonQuality"] = payload.GetValueOrDefault("comparisonQuality"),
                ["continuations"] = payload.GetValueOrDefault("search") is Dictionary<string, object?> search
                    ? search.GetValueOrDefault("continuations")
                    : null,
                ["catalogFingerprint"] = payload.GetValueOrDefault("catalogFingerprint"),

                ["error"] = payload.GetValueOrDefault("error"),
            }, UnattendedTestFiles.JsonOptions));

        Console.WriteLine();
        Console.WriteLine("| 步骤 | 结果 | 详情 | 耗时 ms |");
        Console.WriteLine("|---|---|---|---:|");
        foreach (StepRecord step in steps)
            Console.WriteLine($"| {step.Name} | {step.Status} | {step.Detail.Replace("|", "\\|")} | {step.Milliseconds} |");
        Console.WriteLine();
        Console.WriteLine($"reached={reached} result={resultPath}");
        return exitCode;
    }

    private static object DescribeBudget(HarnessOptions options)
    {
        SolverSearchProfile profile = ModRuntime.ResolveProfile(options);
        return new
        {
            options.Profile,
            profile.BeamWidth,
            profile.MaxExpandedNodes,
            profile.MaxCardBranchesPerNode,
            profile.MaxPileChoiceBranchesPerAction,
            profile.MaxHandChoiceBranchesPerAction,
            options.MaxDegreeOfParallelism,
            options.BudgetMilliseconds,
            options.EarlyTurnExplorationDepth,
            options.EarlyTurnExplorationBudgetMilliseconds,
            options.PotionPolicy,
            options.SearchMode,
            options.UsePortfolio,
            fixedSearchBudget = !options.ProductionBudget,
            enableNoGcRegion = options.EnableNoGcRegion,
            noGcRegionBudgetGigabytes = options.EnableNoGcRegion
                ? options.NoGcRegionBudgetGigabytes
                : (double?)null,
        };
    }

    private static string NextMilestone(string reached) => reached switch
    {
        "none" => "M1",
        "M1" => "M2",
        _ => "M3",
    };

    private static void Step(List<StepRecord> steps, string name, Func<string> body)
    {
        Stopwatch watch = Stopwatch.StartNew();
        try
        {
            string detail = body();
            steps.Add(new StepRecord(name, "ok", detail, watch.ElapsedMilliseconds));
            Console.WriteLine($"[ok]   {name}: {detail} ({watch.ElapsedMilliseconds} ms)");
        }
        catch (Exception error)
        {
            Exception root = Unwrap(error);
            steps.Add(new StepRecord(name, "FAIL", $"{root.GetType().Name}: {root.Message}", watch.ElapsedMilliseconds));
            Console.WriteLine($"[FAIL] {name}: {root.GetType().Name}: {root.Message} ({watch.ElapsedMilliseconds} ms)");
            throw;
        }
    }

    private static Exception Unwrap(Exception error)
    {
        while (error is TargetInvocationException or AggregateException && error.InnerException != null)
            error = error.InnerException;
        return error;
    }

    private static void WriteProgress(HarnessOptions options, string milestone, string status, string note)
    {
        if (options.RequestPath != null)
            return;
        string path = Path.Combine(options.WorkspaceDirectory, "progress.json");
        Directory.CreateDirectory(options.WorkspaceDirectory);
        File.WriteAllText(path, JsonSerializer.Serialize(new { milestone, status, note }, Json));
    }
}

